import{_ as a,o as e,c as t,a3 as _}from"./chunks/framework.DdpBa4_E.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/77-不同阶层的饮食生活.md","filePath":"books/xialiu-shehui/77-不同阶层的饮食生活.md","lastUpdated":1794732511000}'),o={name:"books/xialiu-shehui/77-不同阶层的饮食生活.md"};function s(i,p,r,n,l,d){return e(),t("div",null,[...p[0]||(p[0]=[_('<h2 id="不同阶层的饮食生活" tabindex="-1">不同阶层的饮食生活 <a class="header-anchor" href="#不同阶层的饮食生活" aria-label="Permalink to &quot;不同阶层的饮食生活&quot;">​</a></h2><p>另一方面，这种阶层意识的差别，也明显地表现为饮食生活的不同。</p><p>从“欲求调查”的结果来看，男性在常去的餐饮店方面没有什么阶层的差别。但是对于“松屋”“GUSTO”“JONATHAN’S”等快餐性质的连锁餐饮店，从下流阶层到中流阶层有支持度上升的倾向。</p><p>与男性相比，女性在这方面则有着明显的阶层差别。只有“星巴克”才赢得上流阶层中的众多支持者，其他连锁餐饮店则大多获得了中流阶层女性的支持。而“萨莉亚”“麦当劳”“罗多伦咖啡”“吉野家”“松屋”等则在下流阶层的女性中拥有众多支持者。</p><p>此外，中流阶层的女性对连锁餐饮店的支持程度高得惊人。一般认为，这是由于中流阶层有小孩的女性较多的缘故，当然也存在着上流阶层的女性有意拒绝大众化连锁餐饮店的可能性。</p><p>根据“第二次女性阶层化调查”的结果，可以看到在以下这些选项中，很明显下流阶层女性选择的人数占大多数：</p><p>“经常不吃早餐”（45.3%）（括号内为下流阶层女性所占的比例，下同）</p><p>“用餐时间不固定”（45.9%）</p><p>“觉得吃饭是一件很麻烦的事情”（30.8%）</p><p>“烧饭做菜太烦人”（45.3%）</p><p>“经常在便利店里买盒饭”（20.3%）</p><p>“买食品、饮料时，会选择食品杂货店”（44.2%）</p><p>“曾经过量进食或拒食”（15.7%）</p><p>“经常吃方便面”（17.4%）</p><p>“会留意便利店里新推出的甜点”（23.8%）</p><p>而以下这些选项，阶层越往下，选择的比例越小：</p><p>“喜欢烧饭做菜”（32.0%）</p><p>“经常看杂志烹调专栏的文章”（31.4%）</p><p>“选择食品的时候很在意是否含有添加剂”（14.5%）</p><p>“尽量多食蔬菜”（43.0%）</p><p>“注意营养均衡”（36.6%）</p><p>综上所述，“下流”女性对于饮食生活的关心程度较低。她们觉得烧菜或吃饭是件麻烦的事情，经常不吃早餐，常常食用便利店里的盒饭或方便面，不太关心食品中的添加剂以及营养成分，饮食缺少规律，导致过量进食或拒食的危险性也很高。</p>',22)])])}const u=a(o,[["render",s]]);export{h as __pageData,u as default};
